-- | The differential corpus (@differential/observation_corpus.json@,
-- generated by @observation_corpus.py@ from the pinned reference Engine):
-- each scenario is rebuilt with the Haskell Instance doors and its
-- snapshot, History page, and observed Net document must equal the
-- reference's exactly (member order and int/float spelling included);
-- each recorded refusal must have the reference's exact text.
module Petrus.Observation.CorpusSpec (spec) where

import Control.Monad (forM_)
import Data.Text (Text)
import Data.Text qualified as T
import Petrus.Activity (ActivityFailureFields (..), activityFailure)
import Petrus.Impetus.Instance
import Petrus.Impetus.Petrinet hiding (candidates)
import Petrus.Json (Json (..))
import Petrus.Observation
import Petrus.Observation.Support
import Test.Hspec

door :: HasCallStack => IO (Either InstanceError x) -> IO x
door action = action >>= expectRight . either (Left . renderInstanceError) Right

scenario :: Text -> IO Instance
scenario = \case
  "canonical" -> canonicalInstance
  "projection_pending_result" -> do
    inst <- canonicalInstance
    o <- firstOf <$> inFlight inst
    _ <- door (recordActivityCompletion inst o (Object [("nested", Array [Object [("value", Int 1)]])]) (Just (IntNumber 8)))
    pure inst
  "projection_pending_failure" -> do
    inst <- canonicalInstance
    o <- firstOf <$> inFlight inst
    failure <-
      expectRight
        (activityFailure (ActivityFailureFields "invalid" "InvalidRequest" (Object [("field", String "name")]) False (Just (IntNumber 9))))
    _ <- door (recordActivityFailure inst o failure (Just (IntNumber 8)))
    pure inst
  "projected_and_next_begun" -> do
    inst <- canonicalInstance
    o <- firstOf <$> inFlight inst
    _ <- door (recordActivityCompletion inst o (Object [("total", Float 2.5)]) (Just (IntNumber 8)))
    advance inst
    pure inst
  "pure_pending" -> do
    inst <-
      create
        (netOf (netSpec [place a, place b] [transition work] [arc a work, arc work b]))
        defaultInstanceConfig
          { initialMarking = markingFromList [(a, [Token (Just "Input") (Object [("nested", Array [Int 1])])])]
          , suppliedIdentity = Just "pure-pending"
          }
    advance inst
    pure inst
  "detached" -> do
    inst <-
      create
        (netOf NetSpec {places = [place a, place b], transitions = [Transition {path = work, handler = Just (HandlerSymbol "bridge"), guards = [], timers = []}], arcs = [arc a work, arc work b], completion = Nothing, name = Nothing})
        canonicalConfig
          { initialMarking = markingFromList [(a, [Token (Just "Input") (Object [("items", Array [Object [("value", Int 1)]])])])]
          , suppliedIdentity = Just "detached"
          , constructionInstant = IntNumber 0
          }
    advance inst
    pure inst
  "timed" ->
    create
      (netOf (netSpec [place a] [Transition {path = work, handler = Nothing, guards = [], timers = [Delay (IntNumber 5)]}] [arc a work]))
      defaultInstanceConfig
        { initialMarking = markingFromList [(a, [Token (Just "X") Null])]
        , constructionInstant = IntNumber 2
        , suppliedIdentity = Just "timed"
        }
  "scoped" -> do
    inst <- canonicalInstance
    scope <- door (openScope inst "draft" Nothing)
    door (acceptDelivery inst source [Token (Just "External") (Int 1)] "draft-1" (Just (ScopeGeneration scope)) Nothing) >>= \case
      DeliveryAccepted accepted -> door (completeDelivery inst accepted Nothing) >> pure ()
      other -> expectationFailure ("expected an accepted delivery, got " <> show other)
    _ <- door (closeScope inst scope Nothing)
    pure inst
  "sealed" -> do
    inst <- canonicalInstance
    door (seal inst source Nothing)
    pure inst
  "unicode_places" -> do
    let names = ["\x1d538", "\xff5a", "z", "Z", "\xe9", "a.b", "a"] :: [Text]
        paths = map (either (error . T.unpack) id . netPath) names
        payload index =
          Object
            [ ("text", String "caf\xe9 \x1d538")
            , ("n", Int index)
            , ("f", Float (fromIntegral index / 2))
            ]
    create
      (netOf NetSpec {places = map place paths, transitions = [], arcs = [], completion = Nothing, name = Just "ordering \xe9\x1d538"})
      defaultInstanceConfig
        { initialMarking = markingFromList [(p, [Token (Just "X") (payload i), Token Nothing Null]) | (i, p) <- zip [0 ..] paths]
        , suppliedIdentity = Just "unicode-\xe9"
        }
  other -> error ("unknown scenario " <> T.unpack other)

-- | Each recorded refusal and how the Haskell side reaches it.
refusalOf :: Text -> IO (Either ObservationError Json)
refusalOf = \case
  "delay_float" -> pure (definition (timed (Delay (FloatNumber 1.5))))
  "until_float" -> pure (definition (timed (Until (FloatNumber 1.5))))
  "until_unsafe" -> pure (definition (timed (Until (IntNumber (2 ^ (60 :: Int))))))
  "snapshot_nan" -> badData (Object [("bad", Float (0 / 0))]) (IntNumber 0) >>= fmap snapshot . capture
  "snapshot_inf" -> badData (Array [Int 1, Object [("bad", Float (-1 / 0))]]) (IntNumber 0) >>= fmap snapshot . capture
  "document_unsafe_integer" -> badData (Object [("bad", Int (2 ^ (60 :: Int)))]) (IntNumber 0) >>= fmap netDocument . capture
  "snapshot_float_watermark" -> badData (Int 1) (FloatNumber 7.5) >>= fmap snapshot . capture
  "history_page_-1_1" -> cursor (Int (-1)) (Int 1)
  "history_page_True_1" -> cursor (Bool True) (Int 1)
  "history_page_0.5_1" -> cursor (Float 0.5) (Int 1)
  "history_page_0_0" -> cursor (Int 0) (Int 0)
  "history_page_0_True" -> cursor (Int 0) (Bool True)
  "history_page_0_1.5" -> cursor (Int 0) (Float 1.5)
  "history_page_0_-3" -> cursor (Int 0) (Int (-3))
  "history_page_8_1" -> cursor (Int 8) (Int 1)
  "document_empty" -> do
    o <- canonicalInstance >>= capture
    pure (netDocument (Observation o.observed mempty))
  other -> error ("unknown refusal " <> T.unpack other)
  where
    timed timer = netOf (netSpec [place a] [Transition {path = work, handler = Nothing, guards = [], timers = [timer]}] [arc a work])
    badData payload at' =
      create
        (netOf (netSpec [place a] [] []))
        defaultInstanceConfig
          { initialMarking = markingFromList [(a, [Token (Just "X") payload])]
          , constructionInstant = at'
          , suppliedIdentity = Just "bad-data"
          }
    cursor afterCursor limit = do
      o <- canonicalInstance >>= capture
      pure (historyCursor afterCursor limit >>= \(x, y) -> historyPage o.observed.identity o.records x y)

spec :: Spec
spec = describe "observation differential corpus" $ do
  corpus <- runIO (corpusFile >>= readJsonFile)
  describe "scenarios" $
    forM_ (objectMembers (member "scenarios" corpus)) $ \(name, expected) ->
      it (T.unpack name) $ do
        o <- scenario name >>= capture
        observedSnapshot <- expectRight (snapshot o)
        observedSnapshot `shouldBeExactly` member "snapshot" expected
        observedPage <- expectRight (historyPage o.observed.identity o.records 0 1000)
        observedPage `shouldBeExactly` member "history_page" expected
        observedDocument <- expectRight (netDocument o)
        observedDocument `shouldBeExactly` member "net_document" expected
  describe "refusals" $
    forM_ (objectMembers (member "errors" corpus)) $ \(name, expected) ->
      it (T.unpack name) $
        refusalOf name >>= \case
          Left (ObservationError message) -> String message `shouldBe` expected
          Right value -> expectationFailure ("expected a refusal, got " <> take 200 (show value))
  where
    objectMembers = \case
      Object ms -> ms
      _ -> []
